<?php
if(!defined('ABSPATH')){exit;}if(!current_user_can(SPF_Roles::INVOICES)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para gestionar el área fiscal.','sistema-para-farmacias'));}
global $wpdb;$docs=SPF_Database::table('invoices');$sales=SPF_Database::table('sales');$customers=SPF_Database::table('customers');$adapter=SPF_Fiscal_Manager::active_adapter();$signer=SPF_Fiscal_Signing_Manager::active_signer();$provider=SPF_Fiscal_Signing_Manager::active_credentials_provider();$transport=SPF_Fiscal_Transport_Manager::active_transport();$issuer=SPF_Fiscal_Settings::issuer();$notice=SPF_Fiscal_Manager::consume_notice();$signature_notice=SPF_Fiscal_Signing_Manager::consume_notice();$transport_notice=SPF_Fiscal_Transport_Manager::consume_notice();$internal_labels=SPF_Documents::statuses();$signature_labels=SPF_Fiscal_Signing_Manager::statuses();$transport_labels=SPF_Fiscal_Transport_Manager::statuses();$fiscal_labels=SPF_Documents::fiscal_statuses();$rows=$wpdb->get_results("SELECT i.*,s.sale_number,s.total,s.created_at sale_date,c.name customer_name,c.business_name,c.document_number customer_document_number FROM $docs i LEFT JOIN $sales s ON s.id=i.sale_id LEFT JOIN $customers c ON c.id=s.customer_id ORDER BY i.id DESC LIMIT 200",ARRAY_A);?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Fiscal','sistema-para-farmacias'); ?></h1>
<?php foreach(array_filter([$notice,$signature_notice,$transport_notice]) as $message): $notice_class=$message['type']==='error'?'error':($message['type']==='warning'?'warning':'success'); ?><div class="notice notice-<?php echo esc_attr($notice_class); ?> is-dismissible"><p><?php echo esc_html($message['message']); ?></p></div><?php endforeach; ?>
<div class="spf-panel"><h2><?php esc_html_e('Preflight, firma local y transporte seguro','sistema-para-farmacias'); ?></h2><p><?php esc_html_e('El preflight genera el XML preliminar, la firma local aplica XMLDSig y la verifica criptográficamente, y el dry-run inspecciona el paquete. Ninguna acción transmite comprobantes.', 'sistema-para-farmacias'); ?></p><div class="spf-config-summary"><span><strong><?php esc_html_e('País','sistema-para-farmacias'); ?></strong><?php echo esc_html(SPF_Config::get('name',SPF_Config::country_code())); ?></span><span><strong><?php esc_html_e('Adaptador','sistema-para-farmacias'); ?></strong><?php echo esc_html($adapter?$adapter->code():__('No disponible','sistema-para-farmacias')); ?></span><span><strong><?php esc_html_e('Firmador','sistema-para-farmacias'); ?></strong><?php echo esc_html($signer?$signer->code():__('No disponible','sistema-para-farmacias')); ?></span><span><strong><?php esc_html_e('Credenciales','sistema-para-farmacias'); ?></strong><?php echo esc_html($provider?$provider->code():__('No disponible','sistema-para-farmacias')); ?></span><span><strong><?php esc_html_e('Transporte','sistema-para-farmacias'); ?></strong><?php echo esc_html($transport?($transport->code().' · '.$transport->environment()):__('No disponible','sistema-para-farmacias')); ?></span><span><strong><?php esc_html_e('Emisor','sistema-para-farmacias'); ?></strong><?php echo esc_html($issuer['legal_name']?:__('Sin configurar','sistema-para-farmacias')); ?></span></div><?php if(!$issuer['tax_id']||!$issuer['legal_name']||!$issuer['address']): ?><p class="spf-message error"><?php esc_html_e('Completa primero la identidad fiscal del emisor en Configuración.','sistema-para-farmacias'); ?> <a href="<?php echo esc_url(admin_url('admin.php?page=spf-settings')); ?>"><?php esc_html_e('Ir a Configuración','sistema-para-farmacias'); ?></a></p><?php endif; ?><p class="description"><?php esc_html_e('El certificado PKCS#12 y su contraseña se leen exclusivamente desde entorno seguro o wp-config mediante SPF_FISCAL_P12_PATH y SPF_FISCAL_P12_PASSWORD. No se guardan en WordPress. Producción continúa bloqueada.', 'sistema-para-farmacias'); ?></p></div>
<div class="spf-panel"><div class="spf-table-scroll spf-table-wide"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Comprobante','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Venta','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cliente','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Interno','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Firma','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Transporte','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Fiscal','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Estrategia','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Acciones','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="10"><?php esc_html_e('No hay comprobantes.','sistema-para-farmacias'); ?></td></tr><?php endif; ?><?php foreach($rows as $row): $internal=sanitize_key($row['internal_status']?:$row['sunat_status']);$signature_status=sanitize_key($row['signature_status']?:'not_signed');$transport_status=sanitize_key($row['transport_status']?:'not_prepared');$fiscal=sanitize_key($row['fiscal_status']?:'not_sent');$strategy=SPF_Fiscal_Transport_Manager::strategy_for_document($row['document_type']); ?><tr><td><strong><?php echo esc_html($row['serie'].'-'.$row['correlative']); ?></strong><br><small><?php echo esc_html($row['document_type']); ?></small></td><td><?php echo esc_html($row['sale_number']); ?><br><small><?php echo esc_html($row['sale_date']); ?></small></td><td><?php echo esc_html($row['business_name']?:$row['customer_name']?:'—'); ?><br><small><?php echo esc_html($row['customer_document_number']); ?></small></td><td><?php echo esc_html(SPF_Config::money($row['total'])); ?></td><td><?php echo esc_html($internal_labels[$internal]??$internal); ?></td><td><?php echo esc_html($signature_labels[$signature_status]??$signature_status); ?></td><td><?php echo esc_html($transport_labels[$transport_status]??$transport_status); ?></td><td><?php echo esc_html($fiscal_labels[$fiscal]??$fiscal); ?></td><td><code><?php echo esc_html($strategy); ?></code></td><td><div class="spf-form-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('spf_prepare_fiscal_document'); ?><input type="hidden" name="action" value="spf_prepare_fiscal_document"><input type="hidden" name="document_id" value="<?php echo esc_attr($row['id']); ?>"><button class="button" <?php disabled(!$adapter); ?>><?php esc_html_e('Preflight','sistema-para-farmacias'); ?></button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('spf_fiscal_sign_local'); ?><input type="hidden" name="action" value="spf_fiscal_sign_local"><input type="hidden" name="document_id" value="<?php echo esc_attr($row['id']); ?>"><button class="button" <?php disabled(!$adapter||!$signer||!$provider); ?>><?php esc_html_e('Firmar y verificar','sistema-para-farmacias'); ?></button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('spf_fiscal_transport_dry_run'); ?><input type="hidden" name="action" value="spf_fiscal_transport_dry_run"><input type="hidden" name="document_id" value="<?php echo esc_attr($row['id']); ?>"><button class="button button-primary" <?php disabled(!$adapter||!$transport); ?>><?php esc_html_e('Dry-run','sistema-para-farmacias'); ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div></div>
